<script setup>
import { computed, onMounted, ref, watch } from 'vue';import { Plus, ArrowLeftRight, Check, X, CircleCheckBig } from '@lucide/vue'
import { api } from '../../services/api';import { authStore } from '../../stores/auth';import { uiStore } from '../../stores/ui';import { money, date } from '../../utils'
import PageHeader from '../../components/PageHeader.vue';import LoadingBlock from '../../components/LoadingBlock.vue';import EmptyState from '../../components/EmptyState.vue';import StatusBadge from '../../components/StatusBadge.vue';import BaseModal from '../../components/BaseModal.vue';import PaginationBar from '../../components/PaginationBar.vue'
const isAdmin=computed(()=>authStore.isAdmin.value),tab=ref('offers'),loading=ref(true),rows=ref([]),meta=ref({page:1,limit:20,total:0}),status=ref(''),modal=ref(false),busy=ref(false),players=ref([]),clubs=ref([]),seasons=ref([]),form=ref({player_id:'',buyer_club_id:'',transfer_type:'PAID',transfer_fee:'0',new_salary_per_season:'0',contract_start_season_id:'',contract_end_season_id:'',note:''})
async function load(page=1){loading.value=true;try{const path=tab.value==='offers'?'/transfer-offers':'/transfers/history';const r=await api.get(path,{page,limit:20,status:tab.value==='offers'?status.value:''});rows.value=r.data;meta.value=r.meta}catch(e){uiStore.notify(e.message,'error')}finally{loading.value=false}}
watch([tab,status],()=>load(1));onMounted(async()=>{try{const [p,c,s]=await Promise.all([api.get('/players',{limit:100}),isAdmin.value?api.get('/clubs',{limit:100,status:'APPROVED'}):api.get('/public/clubs',{limit:100},{auth:false}),api.get('/seasons')]);players.value=p.data;clubs.value=c.data;seasons.value=s.data}catch{}load()})
function openCreate(){form.value={player_id:'',buyer_club_id:isAdmin.value?'':authStore.user.value.clubId,transfer_type:'PAID',transfer_fee:'0',new_salary_per_season:'0',contract_start_season_id:'',contract_end_season_id:'',note:''};modal.value=true}
async function create(){busy.value=true;try{await api.post('/transfer-offers',form.value);uiStore.notify('Đã gửi đề nghị chuyển nhượng.');modal.value=false;load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function setStatus(row,newStatus){try{await api.patch(`/transfer-offers/${row.id}/status`,{status:newStatus});uiStore.notify('Đã cập nhật đề nghị.');load(meta.value.page)}catch(e){uiStore.notify(e.message,'error')}}
async function complete(row){try{await api.post(`/transfer-offers/${row.id}/complete`,{});uiStore.notify('Đã hoàn tất chuyển nhượng, cập nhật ví và hợp đồng.');load(meta.value.page)}catch(e){uiStore.notify(e.message,'error')}}
</script>
<template><div><PageHeader eyebrow="Transfer Market" title="Chuyển nhượng" description="Theo dõi đề nghị mua cầu thủ, chuyển nhượng tự do, phí chuyển nhượng và lịch sử hoàn tất."><button class="btn btn-primary" @click="openCreate"><Plus :size="17"/>Tạo đề nghị</button></PageHeader><div class="toolbar"><div class="tabs"><button class="btn" :class="{active:tab==='offers'}" @click="tab='offers'"><ArrowLeftRight :size="17"/>Đề nghị</button><button class="btn" :class="{active:tab==='history'}" @click="tab='history'"><CircleCheckBig :size="17"/>Lịch sử</button></div><select v-if="tab==='offers'" v-model="status" class="select status-filter"><option value="">Tất cả trạng thái</option><option value="SENT">Đã gửi</option><option value="ACCEPTED">Đã chấp nhận</option><option value="REJECTED">Từ chối</option><option value="COMPLETED">Hoàn tất</option></select></div><LoadingBlock v-if="loading"/><EmptyState v-else-if="!rows.length"/><div v-else class="glass card table-card"><div class="table-wrap"><table><thead><tr v-if="tab==='offers'"><th>Cầu thủ</th><th>Từ</th><th>Đến</th><th>Loại</th><th>Phí</th><th>Lương mới</th><th>Trạng thái</th><th></th></tr><tr v-else><th>Thời gian</th><th>Cầu thủ</th><th>Từ</th><th>Đến</th><th>Loại</th><th>Phí</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><template v-if="tab==='offers'"><td><b>{{ row.player_name }}</b></td><td>{{ row.seller_club_name||'Tự do' }}</td><td>{{ row.buyer_club_name }}</td><td>{{ row.transfer_type }}</td><td>{{ money(row.transfer_fee) }}</td><td>{{ money(row.new_salary_per_season) }}</td><td><StatusBadge :status="row.status"/></td><td><div class="actions"><button v-if="['SENT','DRAFT'].includes(row.status)" class="btn btn-sm btn-success" @click="setStatus(row,'ACCEPTED')"><Check :size="14"/></button><button v-if="['SENT','DRAFT'].includes(row.status)" class="btn btn-sm btn-danger" @click="setStatus(row,'REJECTED')"><X :size="14"/></button><button v-if="isAdmin&&row.status==='ACCEPTED'" class="btn btn-sm btn-primary" @click="complete(row)">Hoàn tất</button></div></td></template><template v-else><td>{{ date(row.completed_at,true) }}</td><td><b>{{ row.player_name }}</b></td><td>{{ row.from_club_name||'Tự do' }}</td><td>{{ row.to_club_name }}</td><td>{{ row.transfer_type }}</td><td>{{ money(row.transfer_fee) }}</td></template></tr></tbody></table></div><PaginationBar v-bind="meta" @change="load"/></div><BaseModal :open="modal" title="Tạo đề nghị chuyển nhượng" @close="modal=false" width="760px"><form class="form-grid" @submit.prevent="create"><label class="form-group full"><span class="label">Cầu thủ</span><select v-model="form.player_id" class="select" required><option value="">Chọn cầu thủ</option><option v-for="p in players" :key="p.id" :value="p.id">{{ p.full_name }} · {{ p.club_name||'Tự do' }}</option></select></label><label v-if="isAdmin"><span class="label">CLB mua</span><select v-model="form.buyer_club_id" class="select" required><option value="">Chọn CLB</option><option v-for="c in clubs" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label><span class="label">Loại chuyển nhượng</span><select v-model="form.transfer_type" class="select"><option value="PAID">Có phí</option><option value="FREE">Tự do</option></select></label><label v-if="form.transfer_type==='PAID'"><span class="label">Phí chuyển nhượng</span><input v-model="form.transfer_fee" type="number" min="0" class="input"/></label><label><span class="label">Lương mới/mùa</span><input v-model="form.new_salary_per_season" type="number" min="0" class="input" required/></label><label><span class="label">Mùa bắt đầu</span><select v-model="form.contract_start_season_id" class="select" required><option value="">Chọn mùa</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label><span class="label">Mùa kết thúc</span><select v-model="form.contract_end_season_id" class="select"><option value="">Không xác định</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label class="form-group full"><span class="label">Ghi chú</span><textarea v-model="form.note" class="textarea"/></label><div class="form-group full actions"><button class="btn" type="button" @click="modal=false">Hủy</button><button class="btn btn-primary" :disabled="busy">{{ busy?'Đang gửi...':'Gửi đề nghị' }}</button></div></form></BaseModal></div></template>
<style scoped>.toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:18px}.tabs{display:flex;gap:8px}.tabs .active{background:linear-gradient(135deg,var(--primary),var(--primary-2));border-color:transparent}.status-filter{width:210px}.table-card{padding:0;overflow:hidden}.actions{display:flex;gap:5px;justify-content:flex-end}.form-group.full.actions{display:flex;justify-content:flex-end;gap:9px}@media(max-width:650px){.toolbar{align-items:stretch;flex-direction:column}.status-filter{width:100%}}</style>
